import math

def to_base_b_str(n, b):
    if n == 0:
        return "0"
    if b > 36:
        raise ValueError("Base too large")
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    res = ""
    while n > 0:
        res = chars[n % b] + res
        n //= b
    return res

while True:
    b = rng.randint(4, 12)
    k = rng.randint(3, 5)
    num_digits = rng.randint(3, 5)

    digits = [rng.randint(0, b - 1) for _ in range(num_digits)]

    if all(d == 0 for d in digits):
        continue

    # To ensure the problem requires PIE, we want instances where the simpler formula
    # for positive integers (product of C(d_i-1, k-1)) doesn't work. This happens
    # if any d_i < k-1. We can encourage this by retrying if all d_i >= k-1.
    if all(d >= k - 1 for d in digits):
        if rng.random() < 0.75:
            continue

    S_val = 0
    for i, d in enumerate(digits):
        S_val += d * (b**i)

    # Calculate the answer using PIE
    f = {}
    for m in range(k + 1):
        if m == 0:
            f[0] = 1 if S_val == 0 else 0
            continue

        prod = 1
        for d in digits:
            prod *= math.comb(d + m - 1, m - 1)
        f[m] = prod

    ans = 0
    for j in range(k + 1):
        term = ((-1)**j) * math.comb(k, j) * f[k - j]
        ans += term

    if 100 < ans < 10000000:
        S_str = to_base_b_str(S_val, b)
        return {
            'k_val': k,
            'base': b,
            'S_str': S_str,
            'S_val': S_val # For verifier
        }

